using MetaheuristicsPlatform.Parameters;
namespace MetaheuristicsPlatform.Algorithms.EquilibriumOptimizer;
public sealed class EquilibriumOptimizerParameters : IMetaheuristicParameters { public int PopulationSize { get; init; }=30; public int MaximumIterations { get; init; }=200; public double ExplorationConstant { get; init; }=2.0; public double ExploitationConstant { get; init; }=1.0; public double GenerationProbability { get; init; }=0.5; public void Validate(){if(PopulationSize<4)throw new ArgumentOutOfRangeException(nameof(PopulationSize));if(MaximumIterations<=0)throw new ArgumentOutOfRangeException(nameof(MaximumIterations));if(!double.IsFinite(ExplorationConstant)||ExplorationConstant<=0.0)throw new ArgumentOutOfRangeException(nameof(ExplorationConstant));if(!double.IsFinite(ExploitationConstant)||ExploitationConstant<=0.0)throw new ArgumentOutOfRangeException(nameof(ExploitationConstant));if(!double.IsFinite(GenerationProbability)||GenerationProbability<0.0||GenerationProbability>1.0)throw new ArgumentOutOfRangeException(nameof(GenerationProbability));} }
